-- Domain invariants and operational indexes, applied after the schema.
ALTER TABLE users ADD CHECK(role IN ('CUSTOMER','RESTAURANT_OWNER','DELIVERY_PARTNER','ADMIN'));
ALTER TABLE users ADD CHECK(status IN ('ACTIVE','INACTIVE','SUSPENDED'));
ALTER TABLE stations ADD CHECK(radius_km>0 AND latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180);
ALTER TABLE stations ADD CHECK(status IN ('ACTIVE','INACTIVE'));
ALTER TABLE restaurants ADD CHECK(latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180);
ALTER TABLE menu_items ADD CHECK(base_price>=0 AND COALESCE(preparation_minutes,0)>=0);
ALTER TABLE cart_items ADD CHECK(quantity>0 AND quantity<=99);
ALTER TABLE order_items ADD CHECK(quantity>0 AND quantity<=99 AND unit_price>=0);
ALTER TABLE orders ADD CHECK(subtotal>=0 AND delivery_fee>=0 AND tax_amount>=0 AND discount_amount>=0 AND total_amount=subtotal+delivery_fee+tax_amount-discount_amount AND currency='INR');
ALTER TABLE payment_intents ADD CHECK(amount_paise>0 AND currency='INR');
ALTER TABLE payment_intents ADD CHECK((purpose='ORDER' AND order_id IS NOT NULL AND restaurant_id IS NULL AND delivery_agent_id IS NULL) OR (purpose='RESTAURANT_REGISTRATION' AND restaurant_id IS NOT NULL AND order_id IS NULL AND delivery_agent_id IS NULL) OR (purpose='AGENT_REGISTRATION' AND delivery_agent_id IS NOT NULL AND order_id IS NULL AND restaurant_id IS NULL));
ALTER TABLE registration_fees ADD CHECK((restaurant_id IS NOT NULL)::int+(delivery_agent_id IS NOT NULL)::int=1);
ALTER TABLE registration_fees ADD CHECK(amount_paise>=0 AND currency='INR');
ALTER TABLE payments ADD CHECK(amount_paise>0 AND currency='INR');
ALTER TABLE refunds ADD CHECK(amount_paise>0);
ALTER TABLE financial_transactions ADD CHECK(amount_paise>0 AND direction IN ('DEBIT','CREDIT') AND currency='INR');
ALTER TABLE restaurant_earnings ADD CHECK(gross_amount_paise>=0 AND fee_amount_paise>=0 AND net_amount_paise=gross_amount_paise-fee_amount_paise+adjustment_amount_paise);
ALTER TABLE delivery_agent_earnings ADD CHECK(base_amount_paise>=0 AND incentive_amount_paise>=0 AND net_amount_paise=base_amount_paise+incentive_amount_paise+adjustment_amount_paise);
ALTER TABLE restaurant_payouts ADD CHECK(amount_paise>0);
ALTER TABLE delivery_agent_payouts ADD CHECK(amount_paise>0);
ALTER TABLE restaurant_payout_allocations ADD CHECK(amount_paise>0);
ALTER TABLE delivery_agent_payout_allocations ADD CHECK(amount_paise>0);
ALTER TABLE cash_collections ADD CHECK(amount_due_paise>=0 AND amount_collected_paise>=0);
ALTER TABLE coupons ADD CHECK(discount_type IN ('FLAT','PERCENTAGE') AND discount_value>0 AND (discount_type<>'PERCENTAGE' OR discount_value<=100));
ALTER TABLE coupons ADD CHECK(min_order_amount_paise>=0 AND (max_discount_amount_paise IS NULL OR max_discount_amount_paise>0) AND (usage_limit IS NULL OR usage_limit>0) AND (valid_until IS NULL OR valid_until>valid_from));
ALTER TABLE coupon_usages ADD CHECK(discount_amount_paise>0);

CREATE UNIQUE INDEX coupon_case_insensitive ON coupons(upper(code));
CREATE UNIQUE INDEX one_active_cart_per_user ON carts(user_id) WHERE status='ACTIVE' AND deleted_at IS NULL;
CREATE UNIQUE INDEX cart_selection ON cart_items(cart_id,menu_item_id,variant_id) NULLS NOT DISTINCT WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX one_order_restaurant_earning ON restaurant_earnings(order_id);
CREATE UNIQUE INDEX one_order_rider_earning ON delivery_agent_earnings(order_id);
CREATE UNIQUE INDEX one_active_assignment ON delivery_assignments(order_id) WHERE status IN ('ASSIGNED','ACCEPTED','PICKED_UP','OUT_FOR_DELIVERY') AND deleted_at IS NULL;
CREATE UNIQUE INDEX captured_order_payment ON payments(order_id) WHERE status='CAPTURED';
CREATE UNIQUE INDEX provider_order_identity ON payment_intents(provider_order_id) WHERE provider_order_id IS NOT NULL;
CREATE UNIQUE INDEX payment_intent_idempotency ON payment_intents(idempotency_key);
CREATE UNIQUE INDEX provider_payment_identity ON payments(provider_payment_id) WHERE provider_payment_id IS NOT NULL;
CREATE UNIQUE INDEX provider_refund_identity ON refunds(provider_refund_id) WHERE provider_refund_id IS NOT NULL;
CREATE UNIQUE INDEX provider_webhook_identity ON payment_webhook_events(provider,provider_event_id);
CREATE UNIQUE INDEX ledger_event_identity ON financial_transactions(event_key);
CREATE UNIQUE INDEX restaurant_registration_fee ON registration_fees(restaurant_id) WHERE restaurant_id IS NOT NULL;
CREATE UNIQUE INDEX agent_registration_fee ON registration_fees(delivery_agent_id) WHERE delivery_agent_id IS NOT NULL;
CREATE UNIQUE INDEX order_cash_collection ON cash_collections(order_id);
CREATE INDEX activity_entity_history ON system_activity_logs(entity_type,entity_id,occurred_at);
CREATE INDEX order_payment_status ON payments(order_id,status);
CREATE INDEX restaurant_earning_status ON restaurant_earnings(restaurant_id,status);
CREATE INDEX agent_earning_status ON delivery_agent_earnings(delivery_agent_id,status);
CREATE INDEX restaurant_payout_status ON restaurant_payouts(restaurant_id,status);
CREATE INDEX agent_payout_status ON delivery_agent_payouts(delivery_agent_id,status);
